#define GCREG_VIDEO_TL_X_END_FIELD 11

/* Top boundary of video window. NOTE: This field is double buffered.  */
#define GCREG_VIDEO_TL_Y_START_FIELD 16
#define GCREG_VIDEO_TL_Y_END_FIELD 27

