#define GCREG_FRAME_BUFFER_SIZE_WIDTH_END_FIELD 11

/* video height. NOTE: This field is double buffered.  */
#define GCREG_FRAME_BUFFER_SIZE_HEIGHT_START_FIELD 16
#define GCREG_FRAME_BUFFER_SIZE_HEIGHT_END_FIELD 27

