#define GCREG_BLEND_STACK_ORDER_ORDER_OVERLAY0_VIDEO_OVERLAY1 0x2
#define GCREG_BLEND_STACK_ORDER_ORDER_OVERLAY0_OVERLAY1_VIDEO 0x3
#define GCREG_BLEND_STACK_ORDER_ORDER_OVERLAY1_VIDEO_OVERLAY0 0x4
