/* only available for arch 0002 and up. */
#define GCREG_OVERLAY_CONFIG_FORMAT_R8G8B8 0x5
/* only available for arch 0002 and up. */
#define GCREG_OVERLAY_CONFIG_FORMAT_A8R5G6B5 0x6
/* NV12 only available for arch 0002 and up.  */
#define GCREG_OVERLAY_CONFIG_FORMAT_NV12 0x7

/* Enable this overlay layer.  NOTE: This field is double buffered.  */
#define GCREG_OVERLAY_CONFIG_ENABLE_START_FIELD 3
#define GCREG_OVERLAY_CONFIG_ENABLE_END_FIELD 3
#define GCREG_OVERLAY_CONFIG_ENABLE_DISABLE 0x0
#define GCREG_OVERLAY_CONFIG_ENABLE_ENABLE 0x1

/* Enable or disable clear. NOTE: This field is double buffered. */
#define GCREG_OVERLAY_CONFIG_CLEAR_EN_START_FIELD 5
#define GCREG_OVERLAY_CONFIG_CLEAR_EN_END_FIELD 5
#define GCREG_OVERLAY_CONFIG_CLEAR_EN_DISABLED 0x0
#define GCREG_OVERLAY_CONFIG_CLEAR_EN_ENABLED 0x1

/* NOTE: This field is double buffered. */
#define GCREG_OVERLAY_CONFIG_SWIZZLE_START_FIELD 17
#define GCREG_OVERLAY_CONFIG_SWIZZLE_END_FIELD 18
#define GCREG_OVERLAY_CONFIG_SWIZZLE_ARGB 0x0
#define GCREG_OVERLAY_CONFIG_SWIZZLE_RGBA 0x1
#define GCREG_OVERLAY_CONFIG_SWIZZLE_ABGR 0x2
#define GCREG_OVERLAY_CONFIG_SWIZZLE_BGRA 0x3

/* NOTE: This field is double buffered. */
#define GCREG_OVERLAY_CONFIG_UV_SWIZZLE_START_FIELD 19
#define GCREG_OVERLAY_CONFIG_UV_SWIZZLE_END_FIELD 19

/* Enable or disable color key. NOTE: This field is double buffered. */
