#define GCREG_OVERLAY_CONFIG_COLOR_KEY_EN_END_FIELD 20
#define GCREG_OVERLAY_CONFIG_COLOR_KEY_EN_DISABLED 0x0
#define GCREG_OVERLAY_CONFIG_COLOR_KEY_EN_ENABLED 0x1

/*
 * The configuration about DECNano on Overlay0. NOTE: This field is double
 * buffered.
 */
#define GCREG_OVERLAY_CONFIG_DEC_MODE_START_FIELD 21
#define GCREG_OVERLAY_CONFIG_DEC_MODE_END_FIELD 23
/* Disable DEC */
#define GCREG_OVERLAY_CONFIG_DEC_MODE_DISABLE 0x0
/* DECNano: non_subsample mode */
