#define GCREG_DBI_CMD_DBI_DSI_LINE_NUMBER_TWO 0x1

/* Only available when DBI type-B. */
#define GCREG_DBI_CMD_DBI_DSI_MODE_START_FIELD 27
#define GCREG_DBI_CMD_DBI_DSI_MODE_END_FIELD 28
/* pixel or parameter only */
#define GCREG_DBI_CMD_DBI_DSI_MODE_NORMAL 0x0
/* DSI start */
