/* DSI continue */
#define GCREG_DBI_CMD_DBI_DSI_MODE_CONTINUE 0x2

#define GCREG_DBI_CMD_DBI_NOT_LAST_START_FIELD 29
#define GCREG_DBI_CMD_DBI_NOT_LAST_END_FIELD 29

