#define DCREG_LAYER4_CONFIG_RESET_START_FIELD 1
#define DCREG_LAYER4_CONFIG_RESET_END_FIELD 1
#define DCREG_LAYER4_CONFIG_RESET_RESET 0x1

/* Force HW copy the shadow register to active register directly.  */
#define DCREG_LAYER4_CONFIG_FORCE_FLIP_START_FIELD 2
#define DCREG_LAYER4_CONFIG_FORCE_FLIP_END_FIELD 2

/* AxiBurstLenSel.  */
