#define DCREG_LAYER11_CONFIG_Count 1
#define DCREG_LAYER11_CONFIG_WriteMask 0x0000000F
#define DCREG_LAYER11_CONFIG_ResetValue 0x00000000

/*
 * This field indicates register switch status.  OK means HW can copy the
 * register from shadow side to active side at the beginning of the frame.
 * Wait means HW cannot copy the register from shadow side to active side at
 * the beginning of the frame.  This register programming is not done by SW.
 * We call the registers configured by SW directly shadow registers.  We
 * call the registers used by HW active registers.
 */
#define DCREG_LAYER11_CONFIG_REG_SWITCH_START_FIELD 0
#define DCREG_LAYER11_CONFIG_REG_SWITCH_END_FIELD 0
#define DCREG_LAYER11_CONFIG_REG_SWITCH_WAIT 0x0
#define DCREG_LAYER11_CONFIG_REG_SWITCH_OK 0x1

/* Reset Layer11 Registers to default value. This bit is WRITE ONLY.  */
#define DCREG_LAYER11_CONFIG_RESET_START_FIELD 1
#define DCREG_LAYER11_CONFIG_RESET_END_FIELD 1
#define DCREG_LAYER11_CONFIG_RESET_RESET 0x1

/* Force HW copy the shadow register to active register directly.  */
#define DCREG_LAYER11_CONFIG_FORCE_FLIP_START_FIELD 2
#define DCREG_LAYER11_CONFIG_FORCE_FLIP_END_FIELD 2

/* AxiBurstLenSel.  */
