/*
 * Register dcregCursorLayerConfig
 * ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 */

/*
 * Cursor Layer Configuration Register.  Cursor Layer attributes control.
 * This register is not buffered.
 */

#define DCREG_CURSOR_LAYER_CONFIG_Address 0x14000
