#define DCREG_PANEL0_DBI_CONFIG2_WR_ASSERT_START_END_FIELD 3

/*
 * Single write period duration. Cycle number=Setting*(DbiAcTimeUnit+1).      **
 * This field must be no less than 3.
 */
